<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { teamService, permissionLabels, inviteStatus, resetTeam, type Team, type Member, type TeamRole, type Invite } from '@/services/team'
import AppModal from '@/components/AppModal.vue'
import { demoMode } from '@/services/quality'
const team = ref<Team>({ members: [], roles: [], invitations: [] }); const tab = ref('members'); const loading = ref(true); const busy = ref(false); const error = ref(''); const notice = ref(''); const search = ref(''); const link = ref(''); const panel = ref(''); const editingId = ref<number>();
const memberForm = reactive({ reason:'', is_admin: false, is_active: true, role_ids: [] as number[] }); const roleForm = reactive({ name: '',description:'',version:1, permissions: [] as string[] }); const inviteForm = reactive({ email: '', is_admin: false, role_ids: [] as number[] })
const roleTool=ref('');const toolTarget=ref<TeamRole|null>(null);const toolInvite=ref(0);const toolName=ref('')
function tool(action:string,r?:TeamRole,id=0){roleTool.value=action;toolTarget.value=r||null;toolInvite.value=id;toolName.value=r?r.name+' (copie)':'';error.value=''}
async function runTool(){busy.value=true;error.value='';try{if(roleTool.value==='duplicate')await teamService.duplicateRole(toolTarget.value!.id,toolName.value);else if(roleTool.value==='resend'){const token=await teamService.resend(toolInvite.value);link.value=`${window.location.origin}/invitation#token=${token}`}else await teamService.roleState(toolTarget.value!,roleTool.value==='activate');roleTool.value='';await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
const pendingRevoke = ref<number | null>(null); const resetting = ref(false)
function toggle<T extends string | number>(values: T[], value: T, event: Event): T[] {
 return (event.target as HTMLInputElement).checked ? [...new Set([...values, value])] : values.filter(x => x !== value)
}
const detail = ref<{ title: string; fields: { label: string; value: string }[]; kind: 'member' | 'role' | 'invite'; id: number } | null>(null)
function viewMember(m: Member) {
 detail.value = { title: m.name, kind: 'member', id: m.id, fields: [
  { label: 'E-mail', value: m.email }, { label: 'État', value: m.is_active ? 'Actif' : 'Suspendu' },
  { label: 'Administration', value: m.is_admin ? 'Administrateur de cette officine' : 'Non administrateur' },
  { label: 'Rôles attribués', value: m.role_ids.map(id => team.value.roles.find(r => r.id === id)?.name).filter(Boolean).join(', ') || 'Aucun rôle attribué' },
 ] }
}
function viewRole(r: TeamRole) {
 detail.value = { title: r.name, kind: 'role', id: r.id, fields: [{ label: 'Permissions', value: r.permissions.map(p => permissionLabels[p] || p).join(', ') || 'Aucune permission métier' }, { label: 'Périmètre', value: 'Cette officine uniquement. Aucune habilitation clinique implicite.' }] }
}
function viewInvite(i: Invite) {
 detail.value = { title: 'Détail de l’invitation', kind: 'invite', id: i.id, fields: [{ label: 'Destinataire', value: i.email }, { label: 'État', value: inviteStatus(i) }, { label: 'Expiration', value: new Date(i.expires_at).toLocaleString('fr-FR') }, { label: 'Administration à l’acceptation', value: i.roles.is_admin ? 'Oui' : 'Non' }, { label: 'Rôles prévus', value: i.roles.role_ids.map(id => team.value.roles.find(r => r.id === id)?.name).filter(Boolean).join(', ') || 'Aucun rôle métier' }, { label: 'Lien personnel', value: 'Pour des raisons de sécurité, le lien n’est affiché qu’une seule fois lors de sa création.' }] }
}
function editDetail() {
 const d = detail.value; detail.value = null
 if (d?.kind === 'member') { const m = team.value.members.find(m => m.id === d.id); if (m) member(m) }
 if (d?.kind === 'role') { const r = team.value.roles.find(r => r.id === d.id); if (r) role(r) }
}
const members = computed(() => team.value.members.filter(m => `${m.name} ${m.email}`.toLowerCase().includes(search.value.toLowerCase())))
async function load() { loading.value = true; error.value = ''; try { team.value = await teamService.list() } catch(e) { team.value = { members: [], roles: [], invitations: [] }; error.value = (e as Error).message } finally { loading.value = false } }
function member(m: Member) { editingId.value = m.id; Object.assign(memberForm, {reason:'', is_admin: m.is_admin, is_active: m.is_active, role_ids: [...m.role_ids] }); panel.value = 'member'; error.value = ''; notice.value = '' }
function role(r?: TeamRole) { editingId.value = r?.id; Object.assign(roleForm, { name: r?.name || '',description:r?.description||'',version:r?.version||1, permissions: [...(r?.permissions || [])] }); panel.value = 'role'; error.value = ''; notice.value = '' }
function invite() { Object.assign(inviteForm, { email: '', is_admin: false, role_ids: [] }); panel.value = 'invite'; link.value = ''; error.value = ''; notice.value = '' }
async function save() {
 busy.value = true; error.value = ''; notice.value = ''
 try {
  if (panel.value === 'member') await teamService.updateMember(editingId.value!, { ...memberForm, role_ids: [...memberForm.role_ids] })
  else if (panel.value === 'role') await teamService.saveRole({ ...roleForm, permissions: [...roleForm.permissions] }, editingId.value)
  else { const token = await teamService.invite(inviteForm.email, { is_admin: inviteForm.is_admin, role_ids: [...inviteForm.role_ids] }); link.value = `${window.location.origin}/invitation#token=${token}`; tab.value = 'invitations' }
  panel.value = ''; notice.value = 'Modification enregistrée.'; await load()
 } catch(e) { error.value = (e as Error).message } finally { busy.value = false }
}
function revoke(id: number) { error.value = ''; pendingRevoke.value = id }
async function confirmAction() {
 busy.value = true; error.value = ''
 try {
  if (resetting.value) { resetTeam(); panel.value = ''; link.value = '' }
  else if (pendingRevoke.value !== null) await teamService.revoke(pendingRevoke.value)
  pendingRevoke.value = null; resetting.value = false; await load(); notice.value = 'Opération effectuée.'
 } catch(e) { error.value = (e as Error).message } finally { busy.value = false }
}
async function copy() { try { await navigator.clipboard.writeText(link.value); notice.value = 'Lien copié. Partagez-le uniquement avec la personne invitée.' } catch { notice.value = 'Copie indisponible : sélectionnez le lien ci-dessous.' } }
function reset() { error.value = ''; resetting.value = true }
function locationOrigin() { return window.location.origin }
onMounted(load)
</script>
<template><div class="page"><div class="page-heading compact"><div><p class="eyebrow">LES BONNES PERSONNES, LES BONS ACCÈS</p><h1>Votre équipe,<br><span class="accent-serif">en toute confiance.</span></h1><p class="page-subtitle">Invitez vos collaborateurs et adaptez les droits de chacun.</p></div><button class="button primary" :disabled="busy || loading" @click="invite">Inviter un membre</button></div><p v-if="error && !panel && !link && pendingRevoke === null && !resetting" class="alert error" role="alert">{{ error }}</p><p v-if="notice" class="alert success" role="status">{{ notice }}</p><AppModal :model-value="!!link" title="Lien d’invitation créé" @update:model-value="link = ''"><div class="invitation-link"><p v-if="notice" role="status" class="alert success">{{ notice }}</p><p>Valable 7 jours et utilisable une seule fois. Aucun e-mail n’a été envoyé automatiquement. Le lien ne sera plus affiché après actualisation.</p><label>Lien à transmettre<input :value="link" readonly @focus="($event.target as HTMLInputElement).select()" /></label><button class="button secondary" @click="copy">Copier le lien</button><RouterLink v-if="demoMode" class="text-link" :to="link.replace(locationOrigin(), '')">Tester l’acceptation →</RouterLink></div><template #footer><button class="button primary" @click="link = ''">Terminer</button></template></AppModal>
<section class="panel"><div class="table-toolbar"><div class="tabs"><button v-for="t in [{id:'members',label:'Membres'},{id:'roles',label:'Rôles & droits'},{id:'invitations',label:'Invitations'}]" :key="t.id" :aria-pressed="tab === t.id" :class="{selected:tab === t.id}" @click="tab = t.id; panel = ''">{{ t.label }}</button></div><label v-if="tab === 'members'" class="search-field"><input v-model="search" type="search" placeholder="Rechercher un membre…" aria-label="Rechercher un membre" /></label><button v-if="tab === 'roles'" class="button secondary" @click="role()">Créer un rôle</button></div><p v-if="loading" class="loading">Chargement de l’équipe…</p><div v-else-if="tab === 'members'" class="table-scroll"><table><thead><tr><th>MEMBRE</th><th>RÔLES</th><th>ACCÈS</th><th>ÉTAT</th><th>ACTIONS</th></tr></thead><tbody><tr v-for="m in members" :key="m.id"><td><strong>{{ m.name }}</strong><small class="table-subtitle">{{ m.email }}</small></td><td>{{ m.role_ids.map(id => team.roles.find(r => r.id === id)?.name).filter(Boolean).join(', ') || 'Aucun rôle attribué' }}</td><td>{{ m.is_admin ? 'Administrateur officine' : 'Selon les rôles' }}</td><td><span class="status-badge" :class="m.is_active ? 'active' : 'rejected'">{{ m.is_active ? 'Actif' : 'Suspendu' }}</span></td><td class="row-actions"><button class="button secondary" :disabled="busy" @click="viewMember(m)">Voir</button><button class="button secondary" :disabled="busy" @click="member(m)">Modifier</button></td></tr></tbody></table><p v-if="!members.length" class="empty-state">Aucun membre à afficher.</p></div><div v-else-if="tab === 'roles'" class="role-grid"><article v-for="r in team.roles" :key="r.id" class="role-card"><h3>{{ r.name }}</h3><ul><li v-for="p in r.permissions" :key="p">{{ permissionLabels[p] || p }}</li><li v-if="!r.permissions.length">Aucune permission métier</li></ul><button class="button secondary" :disabled="busy" @click="viewRole(r)">Voir</button> <button class="button secondary" :disabled="busy" @click="role(r)">Modifier les droits</button><template v-if="!demoMode"><button class="button secondary small" @click="tool('duplicate',r)">Dupliquer</button><button class="button secondary small" @click="tool(r.is_active===false?'activate':'deactivate',r)">{{r.is_active===false?'Réactiver':'Désactiver'}}</button><p class="module-disclaimer">{{r.member_count||0}} membre(s) · {{r.is_active===false?'Inactif':'Actif'}}</p></template></article><p v-if="!team.roles.length" class="empty-state">Créez votre premier rôle personnalisé.</p></div><div v-else class="table-scroll"><table><thead><tr><th>DESTINATAIRE</th><th>DROITS PRÉVUS</th><th>EXPIRATION</th><th>ÉTAT</th><th>ACTION</th></tr></thead><tbody><tr v-for="i in team.invitations" :key="i.id"><td>{{ i.email }}</td><td>{{ i.roles.is_admin ? 'Administrateur · ' : '' }}{{ i.roles.role_ids.map(id => team.roles.find(r => r.id === id)?.name).join(', ') || 'Aucun rôle métier' }}</td><td>{{ new Date(i.expires_at).toLocaleDateString('fr-FR') }}</td><td>{{ inviteStatus(i) }}</td><td class="row-actions"><button class="button secondary" @click="viewInvite(i)">Voir</button><button v-if="!demoMode&&!i.accepted_at&&!i.revoked_at" class="button secondary" @click="tool('resend',undefined,i.id)">Renvoyer</button><button v-if="inviteStatus(i) === 'En attente'" class="button secondary" :disabled="busy" @click="revoke(i.id)">Révoquer</button></td></tr></tbody></table><div v-if="!team.invitations.length" class="empty-state"><h3>Aucune invitation pour le moment</h3><p>Invitez une personne pour lui donner accès à cette officine.</p></div></div></section>
<AppModal :model-value="!!panel" :title="panel === 'role' ? 'Configurer un rôle' : panel === 'invite' ? 'Inviter une personne' : 'Modifier le membre'" :busy="busy" eyebrow="ÉQUIPE & DROITS" @update:model-value="panel = ''"><div class="team-editor"><p v-if="error" class="alert error" role="alert">{{ error }}</p><form @submit.prevent="save"><div class="form-body"><template v-if="panel === 'role'"><label>Description<textarea v-model="roleForm.description" rows="2" maxlength="500"/></label><label>Nom du rôle *<input v-model.trim="roleForm.name" required maxlength="80" placeholder="Ex. Responsable du suivi qualité" /></label><fieldset class="permissions-fieldset"><legend>Permissions métier</legend><label v-for="(label,p) in permissionLabels" :key="p" class="checkbox-label"><input :checked="roleForm.permissions.includes(p)" @change="roleForm.permissions = toggle(roleForm.permissions, p, $event)" type="checkbox" :value="p" /><span>{{ label }}</span></label></fieldset></template><template v-else-if="panel === 'invite'"><label>Adresse e-mail *<input v-model.trim="inviteForm.email" type="email" required maxlength="254" placeholder="collaborateur@example.test" /></label><label class="checkbox-label"><input v-model="inviteForm.is_admin" type="checkbox" /><span>Administrateur de cette officine : gestion de l’équipe et accès au module qualité. Aucun droit clinique implicite.</span></label><fieldset class="permissions-fieldset"><legend>Rôles attribués à l’acceptation</legend><label v-for="r in team.roles.filter(r=>r.is_active!==false)" :key="r.id" class="checkbox-label"><input :checked="inviteForm.role_ids.includes(r.id)" @change="inviteForm.role_ids = toggle(inviteForm.role_ids, r.id, $event)" type="checkbox" :value="r.id" /><span>{{ r.name }}</span></label></fieldset></template><template v-else><label class="checkbox-label"><input v-model="memberForm.is_active" type="checkbox" /><span>Membre actif (désactiver suspend les accès à cette officine dès la prochaine requête)</span></label><label class="checkbox-label"><input v-model="memberForm.is_admin" type="checkbox" /><span>Administrateur de l’officine</span></label><label v-if="!memberForm.is_active">Motif de suspension<textarea v-model="memberForm.reason" required rows="3" maxlength="2000"/></label><fieldset class="permissions-fieldset"><legend>Rôles du membre · plusieurs choix possibles</legend><label v-for="r in team.roles.filter(r=>r.is_active!==false)" :key="r.id" class="checkbox-label"><input :checked="memberForm.role_ids.includes(r.id)" @change="memberForm.role_ids = toggle(memberForm.role_ids, r.id, $event)" type="checkbox" :value="r.id" /><span>{{ r.name }}</span></label></fieldset><p class="field-hint">Le dernier administrateur actif ne peut être suspendu ou privé de ses droits d’administration.</p></template><p class="field-hint">Poste RH, qualification professionnelle et permissions applicatives sont distincts. Les droits cliniques seront traités séparément.</p></div><div class="modal-footer"><button type="button" class="button secondary" :disabled="busy" @click="panel = ''">Annuler</button><button class="button primary" :disabled="busy">{{ busy ? 'Enregistrement…' : panel === 'invite' ? 'Créer le lien d’invitation' : 'Enregistrer' }}</button></div></form></div></AppModal><AppModal :model-value="pendingRevoke !== null || resetting" :title="resetting ? 'Réinitialiser la démonstration équipe ?' : 'Révoquer cette invitation ?'" :busy="busy" size="small" @update:model-value="pendingRevoke = null; resetting = false"><div class="form-body"><p v-if="error" role="alert" class="alert error">{{ error }}</p><p>{{ resetting ? 'Les membres, rôles et invitations fictifs seront restaurés. Les actions qualité et dossiers seront conservés.' : 'Le lien ne pourra plus être utilisé pour rejoindre l’officine. Aucun membre déjà accepté ne sera supprimé.' }}</p></div><template #footer><button class="button secondary" :disabled="busy" @click="pendingRevoke = null; resetting = false">Annuler</button><button class="button primary" :disabled="busy" @click="confirmAction">{{ busy ? 'Enregistrement…' : 'Confirmer' }}</button></template></AppModal><AppModal :model-value="!!detail" :title="detail?.title || 'Détail'" eyebrow="CONSULTATION" @update:model-value="detail = null"><div class="form-body"><dl v-if="detail" class="application-summary"><template v-for="field in detail.fields" :key="field.label"><dt>{{ field.label }}</dt><dd>{{ field.value }}</dd></template></dl></div><template #footer><button class="button secondary" @click="detail = null">Fermer</button><button v-if="detail && detail.kind !== 'invite'" class="button primary" @click="editDetail">Modifier</button></template></AppModal><AppModal :model-value="!!roleTool" title="Confirmer l’opération" :busy="busy" @update:model-value="roleTool=''"><form id="team-tool" class="form-body correction-form" @submit.prevent="runTool"><p v-if="error" class="alert error" role="alert">{{error}}</p><label v-if="roleTool==='duplicate'">Nom de la copie<input v-model="toolName" required maxlength="80"/></label><p v-else-if="roleTool==='resend'">Un nouveau lien remplacera le précédent. Son envoi sera préparé dans l’outbox.</p><p v-else>Les rôles encore attribués doivent être réaffectés avant désactivation. Aucun historique ne sera supprimé.</p></form><template #footer><button class="button secondary" :disabled="busy" @click="roleTool=''">Annuler</button><button class="button primary" :disabled="busy" form="team-tool" type="submit">Confirmer</button></template></AppModal><button v-if="demoMode" class="reset-team" :disabled="busy" @click="reset">Réinitialiser uniquement la démonstration équipe</button></div></template>
